    return events.splice(0, events.length)
  }

  function stats() {
    return {
      handled: handled,
      pending: queue.length,
      clonedBytes: clonedBytes,
      transferredBytes: transferredBytes,
      events: events.length,
      failed: failed.length
    }
  }

  return {
    post: post,
    drain: drain,
    takeEvents: takeEvents,
    stats: stats,
    failed: failed
  }
