{
  check('读写：值一律字符串化，缺失 key 返回 null', () => {
    const st = createStorage({ quotaKB: 5 })
    st.set('n', 42)
    same(st.get('n'), '42')
    same(st.get('missing'), null)
    same(st.keys(), ['n'])
  })
