    same(h.scavenge().promoted, 0)
    same(h.snapshot().young, 1)
    const r = h.scavenge()
    same(r.promoted, 1)
    const snap = h.snapshot()
    same(snap.young, 0)
    same(snap.old, 1)
    same(snap.oldBytes, 8)
    same(snap.promoted, 1)
  })
